CREATE TYPE "ClientStatus" AS ENUM ('ACTIVE','INACTIVE','ARCHIVED');
CREATE TYPE "CampaignStatus" AS ENUM ('DRAFT','PLANNED','ACTIVE','PAUSED','COMPLETED','CANCELLED');
CREATE TYPE "CampaignType" AS ENUM ('SOCIAL_MEDIA','SEO','PAID_ADVERTISING','CONTENT_MARKETING','EMAIL_MARKETING','BRANDING','WEBSITE','INFLUENCER_MARKETING','OTHER');
CREATE TYPE "AssignmentRole" AS ENUM ('PRIMARY','SUPPORTING');
CREATE TABLE "Client" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"name" TEXT NOT NULL,"companyName" TEXT,"industry" TEXT,"websiteUrl" TEXT,"primaryEmail" TEXT,"primaryPhone" TEXT,"addressLine1" TEXT,"addressLine2" TEXT,"city" TEXT,"state" TEXT,"postalCode" TEXT,"countryCode" CHAR(2),"timezone" TEXT,"status" "ClientStatus" NOT NULL DEFAULT 'ACTIVE',"ownerUserId" TEXT,"notes" TEXT,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"archivedAt" TIMESTAMP(3),CONSTRAINT "Client_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),CONSTRAINT "Client_ownerUserId_fkey" FOREIGN KEY ("ownerUserId") REFERENCES "User"("id"),CONSTRAINT "Client_createdBy_fkey" FOREIGN KEY ("createdBy") REFERENCES "User"("id"));
CREATE TABLE "ClientContact" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"clientId" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT,"phone" TEXT,"jobTitle" TEXT,"isPrimary" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "ClientContact_one_primary" ON "ClientContact"("clientId") WHERE "isPrimary" = true;
CREATE TABLE "ClientActivity" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"clientId" TEXT NOT NULL,"actorUserId" TEXT,"activityType" TEXT NOT NULL,"description" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE,FOREIGN KEY ("actorUserId") REFERENCES "User"("id"));
CREATE TABLE "Campaign" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"clientId" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT,"description" TEXT,"campaignType" "CampaignType" NOT NULL,"status" "CampaignStatus" NOT NULL DEFAULT 'DRAFT',"objectiveSummary" TEXT,"startDate" DATE,"endDate" DATE,"budgetAmount" DECIMAL(14,2),"currencyCode" CHAR(3) NOT NULL,"createdBy" TEXT NOT NULL,"updatedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"archivedAt" TIMESTAMP(3),CHECK ("budgetAmount" IS NULL OR "budgetAmount">=0),CHECK ("endDate" IS NULL OR "startDate" IS NULL OR "endDate">="startDate"),FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("clientId") REFERENCES "Client"("id"),FOREIGN KEY ("createdBy") REFERENCES "User"("id"),FOREIGN KEY ("updatedBy") REFERENCES "User"("id"));
CREATE TABLE "CampaignObjective" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"campaignId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"metricType" TEXT,"targetValue" DECIMAL(18,4),"unit" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id") ON DELETE CASCADE);
CREATE TABLE "CampaignTeamAssignment" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"campaignId" TEXT NOT NULL,"teamId" TEXT NOT NULL,"assignmentRole" "AssignmentRole" NOT NULL DEFAULT 'SUPPORTING',"assignedBy" TEXT NOT NULL,"assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"removedAt" TIMESTAMP(3),FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id"),FOREIGN KEY ("teamId") REFERENCES "Team"("id"),FOREIGN KEY ("assignedBy") REFERENCES "User"("id"));
CREATE TABLE "CampaignActivity" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"campaignId" TEXT NOT NULL,"actorUserId" TEXT,"activityType" TEXT NOT NULL,"description" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id") ON DELETE CASCADE,FOREIGN KEY ("actorUserId") REFERENCES "User"("id"));
CREATE INDEX "Client_organizationId_status_idx" ON "Client"("organizationId","status"); CREATE INDEX "Client_organizationId_name_idx" ON "Client"("organizationId","name");
CREATE INDEX "ClientContact_organizationId_clientId_idx" ON "ClientContact"("organizationId","clientId"); CREATE INDEX "ClientActivity_organizationId_clientId_createdAt_idx" ON "ClientActivity"("organizationId","clientId","createdAt");
CREATE UNIQUE INDEX "Campaign_organizationId_slug_key" ON "Campaign"("organizationId","slug"); CREATE INDEX "Campaign_organizationId_status_idx" ON "Campaign"("organizationId","status"); CREATE INDEX "Campaign_organizationId_clientId_idx" ON "Campaign"("organizationId","clientId");
CREATE INDEX "CampaignObjective_organizationId_campaignId_idx" ON "CampaignObjective"("organizationId","campaignId"); CREATE UNIQUE INDEX "CampaignTeamAssignment_campaignId_teamId_key" ON "CampaignTeamAssignment"("campaignId","teamId"); CREATE INDEX "CampaignTeamAssignment_organizationId_campaignId_idx" ON "CampaignTeamAssignment"("organizationId","campaignId"); CREATE INDEX "CampaignActivity_organizationId_campaignId_createdAt_idx" ON "CampaignActivity"("organizationId","campaignId","createdAt");
